/**
 * @file `AttachmentPreviewModal`'s open/close, focus-management, and content-derivation state,
 * split out of the component per this package's own hooks-file convention (mirrors
 * `packages/admin/src/react/components/ConfirmDialog/ConfirmDialog.hooks.tsx` and
 * `usePreviewModalShell.ts`).
 *
 * **Dialog lifecycle.** Native `<dialog>` + `showModal()`, the same primitive already used one file
 * over in `Markdown.tsx`'s `TableBlock` for its wide-table pop-out (`openTableDialog`/
 * `closeTableDialog`) — reused here rather than a third hand-rolled overlay. That gives Tab-cycling
 * focus containment for free from the browser; this hook only adds the two things `TableBlock`
 * does not need: an explicit focus-restore-to-opener (native `close()` does return focus in a real
 * browser, but jsdom's `showModal`/`close` are both unimplemented — see the guard below — so a test
 * asserting the restore has nothing to observe without doing it by hand, the same reason
 * `ConfirmDialog.hooks.tsx` does it explicitly rather than trusting the platform), and the
 * image/text/unsupported content derivation an attachment preview needs that a table pop-out does
 * not.
 *
 * **Why content can be missing entirely.** `attachment-preview-cache.ts` only ever holds bytes this
 * browser itself staged for upload, in this page session (see that module's doc for why the server
 * cannot hand them back). A cache miss - a reload, a different session, the eviction cap - degrades
 * to the honest "unsupported" status rather than a broken image or an empty text pane.
 *
 * **Why image-ness is not decided by `attachment.kind` alone.** `@jini-ai/http-kit`'s
 * `detectAttachmentKind` (`attachments.ts`) now sniffs PNG/JPEG/GIF/WEBP/AVIF signatures - AVIF was
 * added specifically for the bug that motivated this task, brand-checked against the same ISO-BMFF
 * `ftyp` box `@jini-ai/cms`'s media sniffer uses, so a real `.avif` upload now carries `kind:
 * 'image'` from the server. This module's extension fallback stays anyway, for two reasons that are
 * still true even with AVIF fixed: BMP/ICO/SVG are in `IMAGE_PREVIEW_EXTENSIONS` but are not sniffed
 * server-side at all (no `hasBmpSignature`/etc. exists), so `kind` alone would still misclassify
 * those as `'file'`; and gating on `kind` would make ANY future sniffer gap fail the same way this
 * one did, whereas the extension guess plus the `<img>`'s own `onError` (wired by the component) is
 * self-correcting - if the browser cannot actually decode what got attempted, `imageFailed` flips
 * this back to a text/unsupported status rather than showing a broken-image icon or trusting a wrong
 * guess. The two checks cannot disagree in a way that matters: `looksLikeImageAttachment` is an OR,
 * so a server `kind: 'image'` is decisive on its own, and the extension guess is only ever a
 * fallback that `onError` can retract - never a second, competing source of truth for a format the
 * server already classified.
 */
import { useEffect, useState, type KeyboardEvent, type MouseEvent, type RefCallback, type SyntheticEvent } from 'react';
import type { ChatAttachment } from '../../core/index.js';
import { getAttachmentPreviewSource } from '../hooks/attachment-preview-cache.js';
import { formatAttachmentSize } from './attachment-size.js';
import type { AttachmentPreviewNavigation } from './AttachmentGallery.hooks.js';

export type AttachmentPreviewStatus = 'image' | 'text' | 'unsupported';

/** Extensions attempted as an `<img>` even when `attachment.kind` says otherwise — see module doc. */
const IMAGE_PREVIEW_EXTENSIONS = new Set(['png', 'jpg', 'jpeg', 'gif', 'webp', 'avif', 'bmp', 'ico', 'svg']);

/** Extensions shown in a scrollable monospace pane. Deliberately narrow — see task scope: "txt, md, json, csv, and similar", not every source-code language. */
const TEXT_PREVIEW_EXTENSIONS = new Set(['txt', 'md', 'markdown', 'json', 'csv', 'tsv', 'log', 'yaml', 'yml', 'xml']);

/** Hard cap on rendered text-preview characters, so a large attached log/CSV cannot hang the tab painting one giant `<pre>`. */
export const MAX_TEXT_PREVIEW_CHARS = 200_000;

function extensionOf(name: string): string {
  const dot = name.lastIndexOf('.');
  return dot === -1 ? '' : name.slice(dot + 1).toLowerCase();
}

/** Exported for the component's own render branch, which needs the same answer without re-deriving it from `status`. */
export function looksLikeImageAttachment({ attachment }: { attachment: Pick<ChatAttachment, 'kind' | 'name'> }): boolean {
  return attachment.kind === 'image' || IMAGE_PREVIEW_EXTENSIONS.has(extensionOf(attachment.name));
}

/** The image step an arrow key asks for in the preview (`-1`/`1`), or `0` for any other key. */
export function galleryStepForKey({ key }: { key: string }): number {
  if (key === 'ArrowLeft') return -1;
  if (key === 'ArrowRight') return 1;
  return 0;
}

function looksLikeTextAttachment(name: string): boolean {
  return TEXT_PREVIEW_EXTENSIONS.has(extensionOf(name));
}

/**
 * Reads `file` as text via `FileReader`, not the newer `Blob.prototype.text()` promise API: both
 * are supported in every real evergreen browser, but jsdom (this package's test environment,
 * verified directly - `File`/`Blob` here has no `.text`/`.arrayBuffer` at all) implements
 * `FileReader.readAsText` while leaving `.text()` unimplemented. Choosing the form the test
 * environment can actually exercise avoids a test-only monkeypatch of a browser primitive whose
 * production behavior isn't in question - only its jsdom coverage was.
 */
export function readFileAsText(
  { file }: { file: File },
  { createReader = () => new FileReader() }: { createReader?: () => FileReader } = {},
): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = createReader();
    reader.onload = () => resolve(typeof reader.result === 'string' ? reader.result : '');
    reader.onerror = () => reject(reader.error ?? new Error('Failed to read attachment as text'));
    reader.readAsText(file);
  });
}

/**
 * `false` in an environment with no Blob-URL support — real browsers have shipped this for well
 * over a decade, but jsdom (this package's own test environment) never implemented it, and this
 * package cannot assume every embedding host is a browser tab. Feature-detected the same way this
 * file already feature-detects `<dialog>`'s `showModal`/`close`, rather than assumed.
 */
export function canCreateObjectUrl(): boolean {
  return typeof URL !== 'undefined' && typeof URL.createObjectURL === 'function';
}

/**
 * Opens `dialog` as a modal and returns the matching close, which also restores focus to whatever
 * was focused when it opened — see this module's doc on why the restore is explicit rather than left
 * to the browser's own (jsdom-absent) default.
 */
function openModalDialog(dialog: HTMLDialogElement): () => void {
  const trigger = document.activeElement;
  if (typeof dialog.showModal === 'function') {
    if (!dialog.open) dialog.showModal();
  } else {
    dialog.setAttribute('open', '');
  }
  return () => {
    if (typeof dialog.close === 'function') {
      if (dialog.open) dialog.close();
    } else {
      dialog.removeAttribute('open');
    }
    if (trigger instanceof HTMLElement) trigger.focus();
  };
}

/**
 * The `<dialog>`'s callback ref: open on attach, close + restore focus on detach. A callback ref
 * rather than an effect reading a ref object, so the element is always in hand — there is no
 * "not attached" case to guard. React 18 and 19 both call it with the element on mount and `null`
 * on unmount, and attach always precedes detach, so `close` is set by the time it is called.
 */
function createDialogRef(): (dialog: HTMLDialogElement | null) => void {
  let close: () => void;
  return (dialog) => {
    if (dialog) close = openModalDialog(dialog);
    else close();
  };
}

export interface AttachmentTextPreview {
  content: string;
  truncated: boolean;
}

export interface AttachmentPreviewController {
  dialogRef: RefCallback<HTMLDialogElement>;
  status: AttachmentPreviewStatus;
  imageUrl: string | undefined;
  onImageError: () => void;
  textLoading: boolean;
  text: AttachmentTextPreview | undefined;
  sizeLabel: string | null;
  handleNativeCancel: (event: SyntheticEvent<HTMLDialogElement>) => void;
  handleBackdropClick: (event: MouseEvent<HTMLDialogElement>) => void;
  /** ←/→ step through `navigation`'s images; a no-op without it. */
  handleKeyDown: (event: KeyboardEvent<HTMLDialogElement>) => void;
}

/**
 * Drives one `AttachmentPreviewModal` instance for `attachment`. The caller conditionally mounts
 * this (one open attachment at a time per `MessageRow`), so mount = open and unmount = close; there
 * is no `open` boolean to track separately.
 * @complexity Time/space: O(1) plus O(n) in the cached file's byte length for the one-time text
 * read on mount (bounded in practice by the upload route's own 20 MB per-attachment cap, and by
 * {@link MAX_TEXT_PREVIEW_CHARS} for what actually renders).
 */
export function useAttachmentPreviewModal(
  { attachment, onClose, navigation }: { attachment: ChatAttachment; onClose: () => void; navigation?: AttachmentPreviewNavigation | undefined },
  { readText = readFileAsText }: { readText?: (required: { file: File }) => Promise<string> } = {},
): AttachmentPreviewController {
  // Lazy state, not `useCallback`: a new ref identity would make React detach and re-attach it,
  // closing and reopening the dialog. The caller mounts a fresh instance per opened attachment (never
  // reuses one instance across two different open attachments), so there is no "attachment changed
  // while still open" transition for the ref to react to. Previous/next is the one exception: it swaps
  // `attachment` under the same open dialog, keeping focus on the button pressed, so the failure flag
  // below is keyed by path rather than a boolean that would carry over to the next image.
  const [dialogRef] = useState(createDialogRef);
  const [failedImagePath, setFailedImagePath] = useState<string | null>(null);
  const imageFailed = failedImagePath === attachment.path;
  const [imageUrl, setImageUrl] = useState<string | undefined>(undefined);
  const [text, setText] = useState<AttachmentTextPreview | undefined>(undefined);
  const [textLoading, setTextLoading] = useState(false);

  const cachedFile = getAttachmentPreviewSource({ path: attachment.path });
  const attemptImage =
    !imageFailed && cachedFile !== undefined && looksLikeImageAttachment({ attachment: attachment }) && canCreateObjectUrl();
  const attemptText = !attemptImage && cachedFile !== undefined && looksLikeTextAttachment(attachment.name);
  const fallbackStatus: AttachmentPreviewStatus = attemptText ? 'text' : 'unsupported';
  const status: AttachmentPreviewStatus = attemptImage ? 'image' : fallbackStatus;

  // Object URL: created/revoked in an effect (not `useMemo`) so a React 18 Strict Mode double-render
  // can never create two URLs and revoke only one — the cleanup below always pairs with the create
  // that produced the URL currently in state.
  useEffect(() => {
    if (!attemptImage || !cachedFile) {
      setImageUrl(undefined);
      return undefined;
    }
    const url = URL.createObjectURL(cachedFile);
    setImageUrl(url);
    return () => URL.revokeObjectURL(url);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [attemptImage, cachedFile]);

  useEffect(() => {
    if (!attemptText || !cachedFile) {
      setText(undefined);
      return undefined;
    }
    let canceled = false;
    setTextLoading(true);
    readText({ file: cachedFile })
      .then((full) => {
        if (canceled) return;
        const truncated = full.length > MAX_TEXT_PREVIEW_CHARS;
        setText({ content: truncated ? full.slice(0, MAX_TEXT_PREVIEW_CHARS) : full, truncated });
      })
      .catch(() => {
        // A file this extension-list called "text-ish" that fails to decode as text falls back to
        // the honest unsupported view via `text` staying `undefined`, rather than showing garbage.
        if (!canceled) setText(undefined);
      })
      .finally(() => {
        if (!canceled) setTextLoading(false);
      });
    return () => {
      canceled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [attemptText, cachedFile]);

  function handleNativeCancel(event: SyntheticEvent<HTMLDialogElement>): void {
    // Always prevented, same reasoning as `ConfirmDialog.hooks.tsx`: the effect above is the single
    // source of truth for open/closed, so Escape still closes — it just does so through `onClose`
    // (which unmounts this controller) rather than letting the browser desync from React state.
    event.preventDefault();
    onClose();
  }

  function handleBackdropClick(event: MouseEvent<HTMLDialogElement>): void {
    // A `<dialog>` element's own box is sized to its content; a click landing on the `<dialog>`
    // element itself (rather than a descendant) is a click on the backdrop area outside that box.
    // The handler is bound on the `<dialog>`, so `currentTarget` is that element.
    if (event.target === event.currentTarget) onClose();
  }

  function handleKeyDown(event: KeyboardEvent<HTMLDialogElement>): void {
    const step = navigation ? galleryStepForKey({ key: event.key }) : 0;
    if (step === 0 || !navigation) return;
    event.preventDefault();
    if (step < 0) navigation.onPrevious();
    else navigation.onNext();
  }

  return {
    dialogRef,
    status,
    imageUrl,
    onImageError: () => setFailedImagePath(attachment.path),
    textLoading,
    text,
    sizeLabel: formatAttachmentSize({ size: attachment.size }),
    handleNativeCancel,
    handleBackdropClick,
    handleKeyDown,
  };
}

/**
 * @file `MessageList`'s scroll-anchoring state, split out of the component per this package's
 * hooks-file convention (see `AttachmentPreviewModal.hooks.ts`). Pure DOM scroll-anchoring via a ref
 * lives here (presentational), not in the headless `useConversation` hook, per that hook's own
 * "transport-agnostic hooks never touch DOM" contract.
 */
import { useCallback, useEffect, useMemo, useRef, useState, type RefObject, type UIEvent } from 'react';
import { conversationUsage, type ChatUsageSummary } from '../../core/turn-usage.js';
import { projectAcceptedInputEvents } from '../../core/accepted-input.js';
import type { ChatMessage } from '../../core/index.js';
import { nextStickToBottom, startsNewTurn } from './MessageList.rules.js';

export interface MessageListAutoScroll {
  containerRef: RefObject<HTMLDivElement | null>;
  onScroll: (event: UIEvent<HTMLElement>) => void;
  /** True while the user has scrolled up away from the newest messages. */
  awayFromLatest: boolean;
  /** Scrolls to the newest message and resumes following new output. */
  jumpToLatest: () => void;
}

const prefersReducedMotion = () =>
  typeof window !== 'undefined' && (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false);

/** Recompute costs once per immutable transcript snapshot, including saved history on reload. */
export function useConversationUsage({ messages }: { messages: readonly ChatMessage[] }, _optional = {}) {
  const previous = useRef(new Map<string, ChatUsageSummary>());
  return useMemo(() => {
    // Usage and rendering must see the same answer boundaries, including receipts rebuilt on reload.
    const next = conversationUsage({ messages: messages.map(message => message.events === undefined ? message : {
      ...message, events: projectAcceptedInputEvents({ events: message.events }),
    }) });
    // Keep an unchanged summary's identity so memoized rows skip re-rendering while a run streams.
    for (const [id, summary] of next) {
      const old = previous.current.get(id);
      if (old && JSON.stringify(old) === JSON.stringify(summary)) next.set(id, old);
    }
    previous.current = next;
    return next;
  }, [messages]);
}

export function useMessageListAutoScroll(
  { messages, scrollIntent }: { messages: ChatMessage[]; scrollIntent: boolean },
  { onScrolled, reducedMotion = prefersReducedMotion }: { onScrolled?: () => void; reducedMotion?: () => boolean } = {},
): MessageListAutoScroll {
  const containerRef = useRef<HTMLDivElement | null>(null);
  // Whether the transcript was scrolled to its bottom as of the last user scroll or programmatic
  // scroll-to-bottom — read by the ResizeObserver effect below, which only ever sees the DOM AFTER a
  // resize already happened and so cannot recompute "was this at the bottom" from current values.
  // Starts true: a freshly mounted pane opens on the latest turn, same as scrollIntent's own default.
  const stickToBottomRef = useRef(true);
  const previousMessagesRef = useRef<readonly ChatMessage[]>(messages);
  // `scrollTop` at the previous `scroll` event — `nextStickToBottom` needs the direction of travel.
  // Only scroll events write it (a browser fires one for programmatic scrolls too). Starts at
  // Infinity, "no position seen yet", so a first event away from the bottom unsticks as it always did.
  const lastScrollTopRef = useRef(Number.POSITIVE_INFINITY);
  // State mirror of `!stickToBottomRef.current` for the "Jump to latest" button; the ref stays the
  // source of truth for the scroll effects, which must not wait for a render.
  const [awayFromLatest, setAwayFromLatest] = useState(false);

  // Runs BEFORE the scroll effect below (effects run in declaration order), so a send re-sticks in
  // time for that same commit's scroll. The user's own send (or retry) is an explicit "take me to
  // the latest turn": without this, a user who had scrolled up to read history and then sent stayed
  // parked up there, because the stick gate below — correct for streamed chatter — also swallowed
  // their own send (owner-reported "Chat auto-scroll still sticks", todos audit 2026-10-04).
  useEffect(() => {
    if (startsNewTurn({ previous: previousMessagesRef.current, next: messages })) {
      stickToBottomRef.current = true;
      setAwayFromLatest(false);
    }
    previousMessagesRef.current = messages;
  }, [messages]);

  useEffect(() => {
    if (!scrollIntent) return;
    const el = containerRef.current;
    // Gated on `stickToBottomRef`, same as the ResizeObserver effect below: `scrollIntent` turns
    // true on EVERY streamed event (tool-call chatter included, not just a finished reply — see
    // `useConversation.applyRunToAssistantMessage`), so scrolling unconditionally here yanked a user
    // who had deliberately scrolled up to read history back to the bottom on the very next chunk
    // (owner-reported, 2026-08-30). `stickToBottomRef` already reflects the user's own last scroll
    // gesture via the `onScroll` handler below, captured BEFORE this content change, so it is safe
    // to trust here.
    if (el && stickToBottomRef.current) {
      el.scrollTop = el.scrollHeight;
    }
    onScrolled?.();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [scrollIntent, messages]);

  // Re-sticks to the bottom when a message ROW grows after mount with no accompanying `messages`
  // change — the exact case an embedded MCP-UI/A2UI surface hits: it mounts at an initial guessed
  // height (`preferredFrameSize` or `DEFAULT_INITIAL_HEIGHT`), then reports its real, often much
  // taller content height asynchronously via `ui/notifications/size-changed`, entirely inside that
  // surface's own React state (`McpUiHost`). The effect above never re-runs for that, so without this
  // a surface which grows after the one-shot scroll leaves its own action buttons — or, once it
  // resolves, the assistant's next reply — below the stale "bottom" with nothing to bring them back
  // into view. Observes each direct child (one per message row) rather than the scroll container
  // itself: the container's own box is held fixed by its flex/overflow layout, so only its CONTENT
  // grows, which `ResizeObserver` only reports for the element whose box is actually changing.
  // Re-created per `messages` change so a newly mounted row is observed too. Gated on
  // `stickToBottomRef` so a human who scrolled up to read history is never yanked back down by an
  // unrelated row resizing elsewhere in the transcript.
  useEffect(() => {
    const el = containerRef.current;
    if (!el || typeof ResizeObserver !== 'function') return undefined;
    const observer = new ResizeObserver(() => {
      if (!stickToBottomRef.current) return;
      el.scrollTop = el.scrollHeight;
    });
    for (const child of Array.from(el.children)) observer.observe(child);
    return () => observer.disconnect();
  }, [messages]);

  const onScroll = (event: UIEvent<HTMLElement>) => {
    const el = event.currentTarget;
    stickToBottomRef.current = nextStickToBottom(el, { wasSticking: stickToBottomRef.current, previousScrollTop: lastScrollTopRef.current });
    lastScrollTopRef.current = el.scrollTop;
    setAwayFromLatest(!stickToBottomRef.current);
  };

  const jumpToLatest = useCallback(() => {
    const el = containerRef.current;
    if (!el) return;
    // Re-stick first: a smooth scroll's own events move DOWN, which never unsticks, so output that
    // streams in during the animation is followed too.
    stickToBottomRef.current = true;
    setAwayFromLatest(false);
    el.scrollTo({ top: el.scrollHeight, behavior: reducedMotion() ? 'auto' : 'smooth' });
  }, [reducedMotion]);

  return { containerRef, onScroll, awayFromLatest, jumpToLatest };
}

type AnswerValue = string | string[] | undefined;

import { CREDENTIAL_CARD_GUIDANCE, SECRET_REDACTED_NOTICE, type UserTextRedactionOptions } from '../../core/user-text-redaction.js';
import { useUserTextGuard } from '../hooks/useUserTextGuard.js';
/**
 * @module QuestionForm
 *
 * Renders one parsed `<question-form>` as an interactive (or locked/
 * answered) set of controls. Ported from OD's `components/QuestionForm.tsx`
 * (verified 0 OD product references — the file only imports React,
 * `useT()`, and its own question-form types) against `@jini-ai/chat/core`'s
 * `QuestionForm`/`FormQuestion`/`FormOption`/`DirectionCard`/
 * `formatFormAnswers` (the same shapes, lifted verbatim into chat-core
 * already). className/structure kept verbatim (`question-form`/`qf-*`
 * classes — unstyled semantic markup, host supplies CSS); every user-facing
 * string wrapped in `useT()`.
 */
import { forwardRef, useEffect, useImperativeHandle, useMemo, useState, type ChangeEvent, type CSSProperties, type ReactNode } from 'react';
import type { DirectionCard, FormOption, QuestionForm as QuestionFormType } from '../../core/index.js';
import { formatFormAnswers, formOptionValueForLabel, redactQuestionAnswers, isSecretQuestion, withoutSecretQuestionDefaults, questionTextInputProps, questionTextareaProps } from '../../core/index.js';
import { useT } from '../hooks/context.js';
import { SecretInput, SecretTextarea } from '@jini-ai/ui';

export interface QuestionFormFileSubmission {
  questionId: string;
  questionLabel: string;
  files: File[];
}

export interface QuestionFormHandle {
  submit: () => void;
  /** Submit with no answers — every question is optional, so this records each as "(skipped)" and moves on. */
  skipAll: () => void;
}

export interface QuestionFormProps extends UserTextRedactionOptions {
  form: QuestionFormType;
  /** Whether the user can still submit answers — the host disables this once the turn is no longer the most recent one. */
  interactive: boolean;
  submittedAnswers?: Record<string, string | string[]>;
  /** When a host's own Continue button owns the submit, hide this form's footer button and report ready-state via `onReadyChange`. */
  hideInternalSubmit?: boolean;
  draftAnswers?: Record<string, string | string[]>;
  onReadyChange?: (ready: boolean) => void;
  onDraftChange?: (answers: Record<string, string | string[]>) => void;
  onAnswerChange?: (questionId: string, value: string | string[]) => void;
  onSubmit?: (text: string, answers: Record<string, string | string[]>, files?: QuestionFormFileSubmission[]) => void;
}

export const QuestionForm = forwardRef<QuestionFormHandle, QuestionFormProps>(function QuestionForm(
  { form: incomingForm, interactive, submittedAnswers, hideInternalSubmit = false, draftAnswers, onReadyChange, onDraftChange, onAnswerChange, onSubmit, redactUserText, onSecretRedacted },
  ref,
) {
  const t = useT();
  const form = useMemo(() => withoutSecretQuestionDefaults({ form: incomingForm }), [incomingForm]);
  const guard = useUserTextGuard({ ...(redactUserText ? { redactUserText } : {}), ...(onSecretRedacted ? { onSecretRedacted } : {}) });
  const locked = !interactive || !onSubmit || submittedAnswers !== undefined;
  const state = useQuestionAnswers({ form, submittedAnswers, draftAnswers, locked }, { onDraftChange, onAnswerChange });
  const currentAnswers = submittedAnswers ? redactQuestionAnswers({ form, answers: submittedAnswers }).answers : state.answers;
  const ready = answersReady(form, currentAnswers);

  function handleSubmit() {
    if (locked || !onSubmit) return;
    if (!ready) return;
    const safe = redactQuestionAnswers({ form, answers: state.answers }, { ...(redactUserText ? { redactUserText } : {}), onSecretRedacted: guard.notifyRedaction });
    state.setAnswers(safe.answers);
    const files = collectFileSubmissions(form, state.fileAnswers);
    if (files.length > 0) onSubmit(formatFormAnswers({ form: form, answers: safe.answers }), safe.answers, files);
    else onSubmit(formatFormAnswers({ form: form, answers: safe.answers }), safe.answers);
  }

  function handleSkipAll() {
    if (locked || !onSubmit) return;
    const empty: Record<string, string | string[]> = {};
    onSubmit(formatFormAnswers({ form: form, answers: empty }), empty);
  }

  useImperativeHandle(ref, () => ({ submit: handleSubmit, skipAll: handleSkipAll }));
  useEffect(() => {
    onReadyChange?.(!locked && ready);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [onReadyChange, locked, ready]);

  return (
    <div className={`question-form${locked ? ' question-form-locked' : ''}`} data-form-id={form.id}>
      <QuestionFormHead form={form} locked={locked} />
      <div className="question-form-body">
        {form.questions.map((q) => (
          <QuestionField key={q.id} q={q} value={currentAnswers[q.id]} formId={form.id} locked={locked} t={t} {...state.handlers} />
        ))}
      </div>
      {guard.secretRedacted ? <div role="status">{t(SECRET_REDACTED_NOTICE)}</div> : null}
      {hideInternalSubmit ? null : <QuestionFormFoot locked={locked} answered={submittedAnswers !== undefined} ready={ready} submitLabel={form.submitLabel} onSubmit={handleSubmit} />}
    </div>
  );
});

type Question = QuestionFormType['questions'][number];
type Answers = Record<string, string | string[]>;

/** Owns the editable answers plus the picked files; every edit is a no-op once the form is locked. */
function useQuestionAnswers(
  { form, submittedAnswers, draftAnswers, locked }: { form: QuestionFormType; submittedAnswers: Answers | undefined; draftAnswers: Answers | undefined; locked: boolean },
  { onDraftChange, onAnswerChange }: { onDraftChange?: QuestionFormProps['onDraftChange'] | undefined; onAnswerChange?: QuestionFormProps['onAnswerChange'] | undefined } = {},
) {
  const initial = useMemo(() => buildInitialState(form, submittedAnswers, draftAnswers), [form, submittedAnswers, draftAnswers]);
  const [answers, setAnswers] = useState<Answers>(initial);
  const [fileAnswers, setFileAnswers] = useState<Record<string, File[]>>({});

  useEffect(() => {
    setFileAnswers({});
  }, [form.id]);

  useEffect(() => {
    setAnswers((prev) => backfillAnswers(prev, form, submittedAnswers));
  }, [form, submittedAnswers]);

  function update(id: string, value: string | string[]) {
    if (locked) return;
    const next = { ...answers, [id]: value };
    setAnswers(next);
    onDraftChange?.(redactQuestionAnswers({ form, answers: draftSafeAnswers(form, next) }).answers);
    onAnswerChange?.(id, redactQuestionAnswers({ form, answers: { [id]: value } }).answers[id]!);
  }

  function toggleCheckbox(id: string, option: string, maxSelections?: number) {
    if (locked) return;
    const current = Array.isArray(answers[id]) ? (answers[id] as string[]) : [];
    const has = current.includes(option);
    if (!has && maxSelections !== undefined && current.length >= maxSelections) return;
    const next = has ? current.filter((v) => v !== option) : [...current, option];
    const nextAnswers = { ...answers, [id]: next };
    setAnswers(nextAnswers);
    onDraftChange?.(redactQuestionAnswers({ form, answers: draftSafeAnswers(form, nextAnswers) }).answers);
    onAnswerChange?.(id, next);
  }

  function updateCheckboxCustom(q: Question, raw: string) {
    if (locked) return;
    const current = Array.isArray(answers[q.id]) ? (answers[q.id] as string[]) : [];
    const fixed = current.filter((entry) => questionValueIsKnown(q, entry));
    update(q.id, [...fixed, ...splitCustomEntries(raw)]);
  }

  function selectFiles(q: Question, list: FileList | null) {
    const files = Array.from(list ?? []);
    const names = files.map((file) => file.name);
    setFileAnswers((current) => ({ ...current, [q.id]: files }));
    update(q.id, q.multiple ? names : (names[0] ?? ''));
  }

  return { answers, setAnswers, fileAnswers, handlers: { update, toggleCheckbox, updateCheckboxCustom, selectFiles } };
}

function answersReady(form: QuestionFormType, answers: Answers): boolean {
  const withinSelectionLimits = form.questions.every((q) => {
    if (q.type !== 'checkbox' || q.maxSelections === undefined) return true;
    const v = answers[q.id];
    return !Array.isArray(v) || v.length <= q.maxSelections;
  });
  const requiredAnswered = form.questions.every((q) => {
    if (q.required !== true) return true;
    const v = answers[q.id];
    if (Array.isArray(v)) return v.length > 0;
    return typeof v === 'string' && v.trim().length > 0;
  });
  return withinSelectionLimits && requiredAnswered;
}

