function buildInitialState(form: QuestionFormType, submitted: Answers | undefined, draft: Answers | undefined): Answers {
  const out: Answers = {};
  for (const q of form.questions) out[q.id] = initialQuestionValue(q, submitted, draft);
  return out;
}

/** Submitted beats draft beats default beats empty; file drafts are never restored (the File objects are gone). */
function initialQuestionValue(q: Question, submitted: Answers | undefined, draft: Answers | undefined): string | string[] {
  if (submitted?.[q.id] !== undefined) return canonicalizeQuestionValue(q, submitted[q.id]!);
  if (draft?.[q.id] !== undefined && q.type !== 'file') return canonicalizeQuestionValue(q, draft[q.id]!);
  if (q.defaultValue !== undefined) return canonicalizeQuestionValue(q, q.defaultValue);
  return emptyQuestionValue(q);
}

/** Questions that stream in after mount get their initial value; answers already set are kept. */
function backfillAnswers(prev: Answers, form: QuestionFormType, submitted: Answers | undefined): Answers {
  let changed = false;
  const next = { ...prev };
  for (const q of form.questions) {
    if (next[q.id] !== undefined) continue;
    changed = true;
    next[q.id] = initialQuestionValue(q, submitted, undefined);
  }
  return changed ? next : prev;
}

function draftSafeAnswers(form: QuestionFormType, answers: Record<string, string | string[]>): Record<string, string | string[]> {
  const fileQuestionIds = new Set(form.questions.filter((q) => q.type === 'file').map((q) => q.id));
  if (fileQuestionIds.size === 0) return answers;
  const out: Record<string, string | string[]> = {};
  for (const [id, value] of Object.entries(answers)) {
    if (!fileQuestionIds.has(id)) out[id] = value;
  }
  return out;
}

function collectFileSubmissions(form: QuestionFormType, fileAnswers: Record<string, File[]>): QuestionFormFileSubmission[] {
  const out: QuestionFormFileSubmission[] = [];
  for (const q of form.questions) {
    if (q.type !== 'file') continue;
    const files = fileAnswers[q.id] ?? [];
    if (files.length > 0) out.push({ questionId: q.id, questionLabel: q.label, files });
  }
  return out;
}

function emptyQuestionValue(q: QuestionFormType['questions'][number]): string | string[] {
  if (q.type === 'checkbox') return [];
  if (q.type === 'switch') return 'false';
  if (q.type === 'range') return String(q.min ?? 0);
  if (q.type === 'color') return normalizeColorInputValue('');
  return '';
}

function canonicalizeQuestionValue(q: QuestionFormType['questions'][number], value: string | string[]): string | string[] {
  if (Array.isArray(value)) return value.map((entry) => formOptionValueForLabel({ question: q, labelOrValue: entry }));
  return formOptionValueForLabel({ question: q, labelOrValue: value });
}

function shouldRenderCustomChoice(q: QuestionFormType['questions'][number]): boolean {
  return q.allowCustom !== false;
}

function questionValueIsKnown(q: QuestionFormType['questions'][number], value: string): boolean {
  if (q.options?.some((option) => option.value === value || option.label === value)) return true;
  if (q.cards?.some((card) => card.id === value || card.label === value)) return true;
  return false;
}

function customSingleValue(q: QuestionFormType['questions'][number], value: AnswerValue): string {
  if (typeof value !== 'string' || value.length === 0) return '';
  return questionValueIsKnown(q, value) ? '' : value;
}

function customCheckboxValue(q: QuestionFormType['questions'][number], value: AnswerValue): string {
  if (!Array.isArray(value)) return '';
  return value.filter((entry) => !questionValueIsKnown(q, entry)).join(', ');
}

function splitCustomEntries(raw: string): string[] {
  return raw
    .split(/[\n,]/)
    .map((entry) => entry.trim())
    .filter(Boolean);
}

function customInputCharCount(value: string, placeholder: string): number {
  const base = value.length > 0 ? value.length : Math.min(placeholder.length, 22);
  return Math.max(18, Math.min(base + 2, 72));
}

function normalizeColorInputValue(value: AnswerValue): string {
  if (typeof value === 'string' && /^#[0-9a-fA-F]{6}$/.test(value)) return value;
  return '#000000';
}

function fileValueLabel(value: AnswerValue): string {
  if (Array.isArray(value)) return value.join(', ');
  return typeof value === 'string' ? value : '';
}

/**
 * @file Thumbnail state for one attachment on a SENT user message (`SentAttachment.tsx`).
 *
 * A sent image shows as a small thumbnail instead of a filename chip, so the operator can see at a
 * glance which screenshots went with the turn. The bytes come from the same
 * `attachment-preview-cache.ts` the preview modal reads: only files this browser staged for upload in
 * this page session are there (the server cannot hand them back - see that module's doc). Anything
 * else - a non-image, a reload, the cache's eviction cap, a browser that cannot decode the format -
 * stays the filename chip, which still opens the preview modal's honest fallback.
 */
import { useEffect, useState } from 'react';
import type { ChatAttachment } from '../../core/index.js';
import { getAttachmentPreviewSource } from '../hooks/attachment-preview-cache.js';
import { canCreateObjectUrl, looksLikeImageAttachment } from './AttachmentPreviewModal.hooks.js';

/** Blob-URL port, so a test (jsdom has no `URL.createObjectURL`) can supply a fake. */
export interface ObjectUrlPort {
  create: (file: File) => string;
  revoke: (url: string) => void;
}

/** The platform's Blob URLs, or `undefined` where they do not exist (jsdom, non-browser hosts). */
export function platformObjectUrls(): ObjectUrlPort | undefined {
  if (!canCreateObjectUrl()) return undefined;
  return { create: (file) => URL.createObjectURL(file), revoke: (url) => URL.revokeObjectURL(url) };
}

/**
 * The cached file to draw as a thumbnail, or `undefined` when the attachment should stay a chip:
 * not an image (same `looksLikeImageAttachment` rule the preview modal uses), or no bytes cached.
 * @complexity O(1).
 */
export function sentAttachmentThumbnailSource(
  { attachment }: { attachment: Pick<ChatAttachment, 'kind' | 'name' | 'path'> },
  { getSource = getAttachmentPreviewSource }: { getSource?: (required: { path: string }) => File | undefined } = {},
): File | undefined {
  if (!looksLikeImageAttachment({ attachment })) return undefined;
  return getSource({ path: attachment.path });
}

export interface SentAttachmentThumbnail {
  /** Object URL to put in the `<img>`, or `undefined` to render the filename chip. */
  thumbnailUrl: string | undefined;
  /** The `<img>`'s `onError`: an undecodable file falls back to the chip instead of a broken image. */
  onThumbnailError: () => void;
}

/**
 * Creates the thumbnail's object URL on mount and revokes it on unmount (an effect, not `useMemo`,
 * so a Strict Mode double render cannot leak a URL - same reasoning as the preview modal's hook).
 * @param input.hostRendered - True when a host `renderAttachment` draws this chip.
 * @param options.objectUrls - Blob-URL port; defaults to the platform's, `undefined` where absent.
 * @param options.getSource - Preview-cache lookup; defaults to the shared cache.
 * @complexity O(1) per attachment.
 */
export function useSentAttachmentThumbnail(
  { attachment, hostRendered = false }: { attachment: ChatAttachment; hostRendered?: boolean },
  { objectUrls = platformObjectUrls(), getSource = getAttachmentPreviewSource }: {
    objectUrls?: ObjectUrlPort | undefined;
    getSource?: (required: { path: string }) => File | undefined;
  } = {},
): SentAttachmentThumbnail {
  const [failed, setFailed] = useState(false);
  const [thumbnailUrl, setThumbnailUrl] = useState<string | undefined>(undefined);
  // A host `renderAttachment` owns the chip's content, so no thumbnail URL is made for it.
  const source = failed || hostRendered || !objectUrls ? undefined : sentAttachmentThumbnailSource({ attachment }, { getSource });

  useEffect(() => {
    if (!source || !objectUrls) {
      setThumbnailUrl(undefined);
      return undefined;
    }
    const url = objectUrls.create(source);
    setThumbnailUrl(url);
    return () => objectUrls.revoke(url);
    // `objectUrls` is a fresh object per render by default; the file is what the URL is made from.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [source]);

  return { thumbnailUrl, onThumbnailError: () => setFailed(true) };
}

import { useEffect, useRef } from 'react';
import { getAgentModelContext } from '@jini-ai/agentic/dom';

import { CHAT_PANE_AGENT_TOOLS } from '../agent-tools.js';
import type { ChatPaneAgentBridgeAccess, ChatPaneAgentToolAction } from '../types.js';
import { definedProps } from '../../../util/defined-props.js';
import type { UseChatPaneResult } from './useChatPane.hooks.js';

export interface UseChatPaneAgentControlOptions {
  /** Defaults to `false` — agent control is opt-in. */
  enabled?: boolean;
  bridgeAccess?: ChatPaneAgentBridgeAccess;
  /**
   * Register these tools with the in-page WebMCP surface (`document.modelContext`). Defaults to
   * `false`, and that default is a security position rather than caution.
   *
   * The daemon-relayed channel routes every call through `ToolExecutor` — policy, confirmation,
   * timeout, audit. A WebMCP call cannot: it originates inside the page from a browser-native
   * caller, with no run and no principal to authorize against, so there is nothing for the gate to
   * decide on and no run to attribute the action to. Routing it through the daemon would mean
   * inventing both, which is worse than not gating — an invented principal is a gate that says yes.
   *
   * So a host that turns this on is accepting that anything able to reach `document.modelContext`
   * — a browser extension, another script on the page — can drive this pane ungated. That is a
   * legitimate choice for a trusted first-party surface and a bad one for a page hosting untrusted
   * content, which is exactly why it has to be the host's call and not a default.
   */
  webmcp?: boolean;
}

function requireStringField(input: Record<string, unknown>, key: string): string {
  const value = input[key];
  if (typeof value !== 'string' || value.length === 0) throw new Error(`"${key}" is required`);
  return value;
}

function optionalStringField(input: Record<string, unknown>, key: string): string | undefined {
  const value = input[key];
  return typeof value === 'string' && value.length > 0 ? value : undefined;
}

/** Gate for capabilities whose manifest entry sets `requiresConfirmation`. */
function requireConfirmation(input: Record<string, unknown>, what: string): void {
  if (input['confirm'] !== true) {
    throw new Error(`"confirm" must be true — ${what} is destructive and needs explicit acknowledgement`);
  }
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

/** Content read off the page/transcript is untrusted input to whatever model reads it back. */
const MAX_RETURNED_CONTENT = 2000;

function summarizeContent(content: string): {
  content: string;
  truncated: boolean;
  originalLength: number;
} {
  return {
    content: content.slice(0, MAX_RETURNED_CONTENT),
    truncated: content.length > MAX_RETURNED_CONTENT,
    originalLength: content.length,
  };
}

/**
 * Routes through the pane's own guarded send (`rules.ts`'s blocker set + staged attachments +
 * composer reset + batch rotation + activity notification) rather than calling
 * `conversation.sendMessage` directly, so an agent-driven send cannot bypass what the composer
 * enforces. Throws a describable refusal when blocked.
 *
 * It also does not go the other obvious route — `composer.setDraft(prompt)` followed by `send()`.
 * `setDraft` is a React state update and is therefore asynchronous, so the `send()` immediately
 * after it would race the re-render and read a stale draft. Passing the prompt straight to
 * `sendPrompt` is what makes the agent-driven path deterministic.
 */
async function sendMessageAction(pane: UseChatPaneResult, input: Record<string, unknown>): Promise<unknown> {
  await pane.sendPrompt(requireStringField(input, 'prompt'));
  return { sent: true };
}

async function setDraftAction(pane: UseChatPaneResult, input: Record<string, unknown>): Promise<unknown> {
  pane.composer.setDraft(requireStringField(input, 'text'));
  return { ok: true };
}

/**
 * Only a runtime this machine actually offers.
 *
 * `setSelection` normalizes an unknown or unavailable agent to the first available one — correct
 * for the picker, which must not break when a runtime disappears mid-session. For a caller that is
 * told `{ok:true}`, that same behavior is a lie with a safety edge: asking for a constrained
 * runtime and silently getting a more capable one is how a prompt intended for a sandboxed agent
 * reaches a full coding agent instead. So this refuses by name rather than substituting.
 */
async function selectAgentAction(pane: UseChatPaneResult, input: Record<string, unknown>): Promise<unknown> {
  const agentId = requireStringField(input, 'agentId');
  const agent = pane.agents.find((candidate) => candidate.id === agentId);
  if (agent === undefined) {
    const known = pane.agents.map((candidate) => candidate.id).join(', ');
    throw new Error(`unknown agent "${agentId}" — this pane offers: ${known || 'none'}`);
  }
  if (agent.available === false) {
    throw new Error(
      `agent "${agentId}" is not available on this machine`
      + (agent.diagnostic === undefined ? '' : ` (${agent.diagnostic})`),
    );
  }
  const model = optionalStringField(input, 'model');
  const reasoning = optionalStringField(input, 'reasoning');
  pane.setSelection(definedProps({ source: { agentId, model, reasoning } }));
  return { ok: true };
}

async function cancelRunAction(pane: UseChatPaneResult): Promise<unknown> {
  pane.conversation.cancel();
  return { ok: true };
}

async function resetConversationAction(pane: UseChatPaneResult, input: Record<string, unknown>): Promise<unknown> {
  requireConfirmation(input, 'resetting the conversation');
  pane.reset();
  return { ok: true };
}

/**
 * Only a directory the user already approved through the host's native picker. Passing a
 * model-supplied path straight to `selectRecentDirectory` would let the caller choose its own
 * project root, which is the desktop host's human-approval model (`reference-desktop`'s
 * `approvedDirectories`) inverted.
 */
async function setWorkingDirectoryAction(pane: UseChatPaneResult, input: Record<string, unknown>): Promise<unknown> {
  const path = requireStringField(input, 'path');
  if (!pane.recentDirectories.includes(path)) {
    throw new Error(
      'path must be one of the already-approved recentDirectories from chat.get_state; '
      + 'a new directory can only be approved by the user through the host picker',
    );
  }
  await pane.selectRecentDirectory(path);
  return { ok: true };
}

async function getStateAction(pane: UseChatPaneResult): Promise<unknown> {
  const lastMessage = pane.conversation.messages.at(-1);
  const lastMessageSummary = lastMessage === undefined
    ? undefined
    : { role: lastMessage.role, ...summarizeContent(lastMessage.content) };
  return {
    activity: pane.activity,
    selection: pane.selection,
    workingDirectory: pane.workingDirectory,
    recentDirectories: pane.recentDirectories,
    canSend: pane.canSend,
    sendBlocker: pane.sendBlocker,
    messageCount: pane.conversation.messages.length,
    ...definedProps({ source: { lastMessage: lastMessageSummary } }),
    /**
     * Conversation content is user- and agent-authored text, not instructions from the
     * host. A caller reading it back must treat it as data.
     */
    untrustedFields: ['lastMessage.content'],
  };
}

const CHAT_PANE_ACTION_HANDLERS: Record<
  string,
  (pane: UseChatPaneResult, input: Record<string, unknown>) => Promise<unknown>
> = {
  'chat.send_message': sendMessageAction,
  'chat.set_draft': setDraftAction,
  'chat.select_agent': selectAgentAction,
  'chat.cancel_run': cancelRunAction,
  'chat.reset_conversation': resetConversationAction,
  'chat.set_working_directory': setWorkingDirectoryAction,
  'chat.get_state': getStateAction,
};

/** Module-scope so the dispatch itself (one `if`, no branch-per-capability) never pays the
 * per-nested-closure cognitive tax that a `switch` written inline in the effect would; each
 * capability's own logic — and its own explanatory comment — lives in its own top-level
 * function above instead. */
async function runChatPaneAction(
  pane: UseChatPaneResult,
  id: string,
  input: Record<string, unknown>,
): Promise<unknown> {
  const handler = CHAT_PANE_ACTION_HANDLERS[id];
  if (!handler) throw new Error(`unknown chat capability: ${id}`);
  return handler(pane, input);
}

/**
 * Answers one daemon-relayed action on the bridge that delivered it, never on whatever bridge is
 * current: the `invocationId` belongs to that channel, so answering elsewhere would be answering a
 * question nobody asked.
 *
 * Delivery is reported separately from execution: a rejection inside `respondSuccess` is a failure
 * to ANSWER, not a failed action, and must not be re-reported as one. Every delivery attempt is
 * itself guarded so a dead channel cannot surface as an unhandled rejection with the daemon-side
 * invocation left hanging.
 */
async function deliverBridgeAction(
  pane: UseChatPaneResult,
  bridge: ChatPaneAgentBridgeAccess,
  action: ChatPaneAgentToolAction,
): Promise<void> {
  let output: unknown;
  try {
    output = await runChatPaneAction(pane, action.capabilityId, action.input);
  } catch (error) {
    await bridge.respondError(action.invocationId, errorMessage(error)).catch(() => undefined);
    return;
  }
  try {
    await bridge.respondSuccess(action.invocationId, output);
  } catch (deliveryError) {
    await bridge
      .respondError(
        action.invocationId,
        `action succeeded but the result could not be delivered: ${errorMessage(deliveryError)}`,
      )
      .catch(() => undefined);
  }
}

/**
 * Wires the chat pane's own actions (send/draft/selection/cancel/reset/working-directory/state) up
 * to the outside-caller surfaces the pane supports: a daemon-relayed action channel when
 * `bridgeAccess` is supplied, so an HTTP- or MCP-driven caller can reach this SAME live pane
 * instance, and — only when the host sets `webmcp` — in-page WebMCP tool registration
 * (`document.modelContext.registerTool`, feature-detected). Both dispatch through one identical
 * action map (`runChatPaneAction`, module scope above), so the two callers can never diverge in
 * *behavior*.
 *
 * They do differ in *authorization*, and that difference is the reason WebMCP is off by default.
 * The relayed channel arrives having already passed `ToolExecutor`; a WebMCP call has no run and
 * no principal, so it cannot. See {@link UseChatPaneAgentControlOptions.webmcp}.
 */
export function useChatPaneAgentControl({ pane }: { pane: UseChatPaneResult }, options: UseChatPaneAgentControlOptions = {}
): void {
  const enabled = options.enabled ?? false;
  const paneRef = useRef(pane);
  paneRef.current = pane;
  const bridgeAccessRef = useRef(options.bridgeAccess);
  bridgeAccessRef.current = options.bridgeAccess;
  // Presence, not identity: hosts write `agentControl={{...}}` inline in JSX (as every other prop
  // here is written), so depending on the object itself would tear down and re-register all tools
  // on every render, dropping in-flight actions. See the effect's closing comment for the tradeoff.
  const hasBridgeAccess = options.bridgeAccess !== undefined;

  useEffect(() => {
    if (!enabled) return undefined;

    const cleanups: Array<() => void> = [];

    // Not registered unless the host opted in: see `webmcp`'s own doc for why this path cannot be
    // gated and therefore must not be on by default.
    // Feature-detect the draft surface through its shared owner; no `@mcp-b/*` dependency.
    const modelContext = options.webmcp === true ? getAgentModelContext({
      host: { candidates: () => [
        (globalThis as { document?: { modelContext?: unknown } }).document?.modelContext,
        (globalThis as { navigator?: { modelContext?: unknown } }).navigator?.modelContext,
      ] },
    }) : undefined;
    if (modelContext) {
      const controller = new AbortController();
      for (const tool of CHAT_PANE_AGENT_TOOLS) {
        // `registerTool` is async per the draft IDL, and a polyfill may return undefined instead.
        // Normalize both, then swallow: registration is best-effort, and a rejected one must not
        // surface as an unhandled rejection from a React effect.
        const registered = modelContext.registerTool(
          { tool: {
            name: tool.id,
            description: tool.description,
            inputSchema: tool.inputSchema,
            execute: (args) => runChatPaneAction(paneRef.current, tool.id, args ?? {}),
          } },
          { signal: controller.signal },
        );
        void Promise.resolve(registered).catch(() => undefined);
      }
      cleanups.push(() => {
        // Aborting the signal is the spec cleanup path; unregisterTool is optional for polyfills.
        controller.abort();
        if (modelContext.unregisterTool) {
          for (const tool of CHAT_PANE_AGENT_TOOLS) modelContext.unregisterTool({ name: tool.id });
        }
      });
    }

    const subscribedBridge = bridgeAccessRef.current;
    if (subscribedBridge) {
      const unsubscribe = subscribedBridge.subscribe((action) => {
        void deliverBridgeAction(paneRef.current, subscribedBridge, action);
      });
      cleanups.push(unsubscribe);
    }

    return () => {
      for (const cleanup of cleanups) cleanup();
    };
    // Deps are enablement + bridge PRESENCE, never the bridge object: hosts pass `agentControl`
    // inline, so an identity dep would re-register every tool on every render (see
    // `hasBridgeAccess`). Pane, run context, and bridge are all read through refs at call time.
    // Tradeoff: swapping to a genuinely different bridge instance while enabled does not
    // re-subscribe — responses still route to the current bridge via the ref, but the old
    // subscription stays live. A host needing a true swap should toggle `enabled` or remount.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [enabled, hasBridgeAccess]);
}

import { inspect } from 'node:util';
import { redactSecrets } from '@jini-ai/core';
import type { ChatHistoryMaintenance } from "../ports.js";
import { ChatStoreError } from "../errors.js";

/**
 * @file Retention for chat history: deletes every conversation whose `expires_at` has passed.
 *
 * This is the one chat operation that legitimately spans owners (`tenant-scope.ts`'s doc), so it
 * lives here, on the raw chat kernel, and never in a scoped store. Only guest chats carry an
 * `expires_at` (`chatExpiryFor`); a NULL one never expires. Messages, agent sessions and tool
 * approvals go with each conversation through `ON DELETE CASCADE`.
 */

/** How often {@link startChatExpirySweep} re-runs after its boot pass: hourly. */
export const CHAT_EXPIRY_SWEEP_INTERVAL_MS = 60 * 60 * 1000;

/**
 * Deletes every conversation that expired at or before `now`.
 *
 * @param store the chat kernel, or the open `chat.db` handle whose kernel to use.
 * @returns how many conversations were deleted.
 * @complexity One bounded DELETE per 500 expired parents, plus the final partial/empty batch.
 */
export async function sweepExpiredChats(
  { maintenance }: { maintenance: ChatHistoryMaintenance },
  { now = Date.now() }: { now?: number } = {},
): Promise<number> {
  let total = 0;
  let deleted: number;
  try {
    do {
      deleted = await maintenance.sweepExpired({ now }, { limit: 500 });
      total += deleted;
    } while (deleted === 500);
  } catch (error) {
    // Preserve the host timer's existing onError collaborator and retry behavior.
    if (error instanceof ChatStoreError && error.cause !== undefined) throw error.cause;
    throw error;
  }
  return total;
}

/**
 * Runs {@link sweepExpiredChats} once now and then every `intervalMs`, until the returned stop
 * function is called. The timer is `unref`'d so it never keeps the process alive. A failed pass is
 * reported through `onError` and the next pass still runs. A tick that fires while a pass is still
 * running is skipped, so passes never overlap.
 *
 * @returns `stop`: clears the timer and resolves once the pass in flight (if any) has finished, so
 *   the store can be closed right after it. Safe to call more than once.
 */
export function startChatExpirySweep(
  { maintenance }: { maintenance: ChatHistoryMaintenance },
  options: {
    readonly intervalMs?: number;
    readonly now?: () => number;
    readonly onError?: (error: unknown) => void;
  } = {}
): () => Promise<void> {
  const { intervalMs = CHAT_EXPIRY_SWEEP_INTERVAL_MS, now = Date.now } = options;
  const onError =
    options.onError ??
    ((error: unknown) => {
      // eslint-disable-next-line no-console
      console.warn('[chat-expiry-sweep] sweep failed:', redactSecrets({ input: inspect(error) }, { redactPii: false }));
    });
  let active: Promise<void> | undefined;
  const pass = (): void => {
    if (active !== undefined) return;
    active = sweepExpiredChats({ maintenance }, { now: now() })
      .then(() => undefined, onError)
      .finally(() => {
        active = undefined;
      });
  };
  pass();
  const timer = setInterval(pass, intervalMs);
  timer.unref();
  return async () => {
    clearInterval(timer);
    await active;
  };
}
